const HOURS = Array.from({ length: 15 }, (_, i) => i + 9); // 09:00 -> 00:00
const hh = (h) => `${String(h).padStart(2, "0")}:00`;
const ampm = (h) => {
  const suf = h % 24 < 12 ? "a.m." : "p.m.";
  let hr = h % 12; if (hr === 0) hr = 12;
  return { hr, suf };
};
const hourAP = (h) => { const a = ampm(h); return `${a.hr}:00 ${a.suf}`; };
const slotRange = (h) => {
  const a = ampm(h), b = ampm(h + 1);
  const left = a.suf === b.suf ? `${a.hr}:00` : `${a.hr}:00 ${a.suf}`;
  return `${left} – ${b.hr}:00 ${b.suf}`;
};
const money = (n) => `S/ ${Number(n).toFixed(0)}`;

const todayISO = () => new Date().toISOString().slice(0, 10);
const dayLabel = (iso) => {
  const d = new Date(iso + "T00:00:00");
  return d.toLocaleDateString("es-PE", { weekday: "short", day: "2-digit", month: "short" });
};
const nextDays = (n) =>
  Array.from({ length: n }, (_, i) => {
    const d = new Date();
    d.setDate(d.getDate() + i);
    return d.toISOString().slice(0, 10);
  });

