const CODE_CHARS = "23456789ABCDEFGHJKMNPQRSTUVWXYZ";
const genCode = () => Array.from({ length: 8 }, () => CODE_CHARS[Math.floor(Math.random() * CODE_CHARS.length)]).join("");

