// Orden de días para agrupar estadísticas (Lun..Dom).
const WEEK_LABELS = ["Lun", "Mar", "Mié", "Jue", "Vie", "Sáb", "Dom"];
const weekdayLabel = (iso) => {
  const wd = new Date(iso + "T00:00:00").getDay(); // 0=Dom..6=Sáb
  return WEEK_LABELS[wd === 0 ? 6 : wd - 1];
};

