/* ============================ ADMIN LOGIN ============================ */

const ADMIN_USER = "EL ADMIN";
const ADMIN_PASS = "ArenaAzul2026";
// Login para el personal (ventas, inventario, ver reservas) sin acceso a
// ganancias ni al panel completo del dueño. Cambia este usuario/contraseña
// cuando quieras — están acá mismo en el código, igual que el del dueño.
const WORKER_USER = "TRABAJADOR";
const WORKER_PASS = "Arena2026";

function AdminLogin({ onLogin }) {
  const [user, setUser] = useState("");
  const [pass, setPass] = useState("");
  const [err, setErr] = useState(false);
  const [show, setShow] = useState(false);

  const submit = () => {
    const u = user.trim().toUpperCase();
    if (u === ADMIN_USER && pass === ADMIN_PASS) {
      setErr(false); onLogin("owner");
    } else if (u === WORKER_USER && pass === WORKER_PASS) {
      setErr(false); onLogin("worker");
    } else {
      setErr(true);
    }
  };

  return (
    <div className="stack" style={{ paddingTop: 40, maxWidth: 400, margin: "0 auto" }}>
      <div style={{ textAlign: "center" }}>
        <div style={{
          width: 76, height: 76, borderRadius: 20, margin: "0 auto 16px", overflow: "hidden",
          boxShadow: "0 0 0 1px rgba(245,180,0,.25), 0 14px 40px -12px rgba(245,180,0,.3)",
        }}>
          <img src="/logo.png" alt="ARENA AZUL" style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} />
        </div>
        <div className="eyebrow" style={{ color: "var(--amber)" }}>Acceso restringido</div>
        <div className="h1">Panel del dueño</div>
        <div className="sub">Ingresa tu usuario y contraseña para administrar ARENA AZUL.</div>
      </div>

      <div className="card pad stack" style={{ gap: 15 }}>
        <div>
          <span className="field-lab"><UserRound size={13} style={{ verticalAlign: -2, marginRight: 5 }} />Usuario</span>
          <input className="input" style={{ fontFamily: "Inter" }} placeholder="Usuario" value={user}
            onChange={(e) => { setUser(e.target.value); setErr(false); }} />
        </div>
        <div>
          <span className="field-lab"><ShieldCheck size={13} style={{ verticalAlign: -2, marginRight: 5 }} />Contraseña</span>
          <div style={{ display: "flex", gap: 8 }}>
            <input className="input" style={{ fontFamily: "Inter" }} type={show ? "text" : "password"} placeholder="Contraseña" value={pass}
              onChange={(e) => { setPass(e.target.value); setErr(false); }}
              onKeyDown={(e) => e.key === "Enter" && submit()} />
            <button className="btn btn-ghost" onClick={() => setShow((s) => !s)}>{show ? "Ocultar" : "Ver"}</button>
          </div>
        </div>
        {err && (
          <div className="alertbar">
            <AlertTriangle size={16} color="var(--danger)" />
            <span className="sm">Usuario o contraseña incorrectos.</span>
          </div>
        )}
        <button className="btn btn-amber block" onClick={submit}>
          <ShieldCheck size={18} /> Entrar al panel
        </button>
      </div>
    </div>
  );
}

