function AdminView(props) {
  const isOwner = props.authLevel === "owner";
  const ALL_TABS = [
    { id: "resumen", label: "Resumen", icon: LayoutDashboard, ownerOnly: true },
    { id: "reservas", label: "Reservas", icon: CalendarDays },
    { id: "jugadores", label: "Jugadores", icon: Users, ownerOnly: true },
    { id: "quiosco", label: "Quiosco", icon: ShoppingBasket },
    { id: "inventario", label: "Inventario", icon: Boxes },
    { id: "precios", label: "Precios", icon: Tags, ownerOnly: true },
  ];
  const TABS = ALL_TABS.filter((t) => isOwner || !t.ownerOnly);
  const [tab, setTab] = useState(isOwner ? "resumen" : "reservas");

  return (
    <div className="stack" style={{ paddingTop: 20 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
        <div>
          <div className="eyebrow" style={{ color: "var(--amber)" }}>{isOwner ? "Panel del dueño" : "Panel de trabajo"}</div>
          <div className="h1">Control de operación</div>
        </div>
        <button className="btn-ghost" style={{ display: "flex", alignItems: "center", gap: 6 }} onClick={props.onLogout}>
          <LogOut size={14} /> Salir
        </button>
      </div>

      <div className="tabs">
        {TABS.map((t) => (
          <button key={t.id} className={`tab ${tab === t.id ? "on" : ""}`} onClick={() => setTab(t.id)}>
            <t.icon size={15} /> {t.label}
          </button>
        ))}
      </div>

      {tab === "resumen" && <Resumen {...props} />}
      {tab === "reservas" && <Reservas {...props} />}
      {tab === "jugadores" && <Jugadores {...props} />}
      {tab === "quiosco" && <Quiosco {...props} />}
      {tab === "inventario" && <Inventario {...props} />}
      {tab === "precios" && <Precios {...props} />}
    </div>
  );
}

function Jugadores({ clients, bookings }) {
  const map = {};
  clients.forEach((c) => { map[c.phone] = { ...c, reservas: 0, gastado: 0 }; });
  bookings.forEach((b) => {
    if (!b.phone) return;
    if (!map[b.phone]) map[b.phone] = { nombres: b.client, phone: b.phone, reservas: 0, gastado: 0 };
    map[b.phone].reservas += 1;
    if (b.status === "confirmado") map[b.phone].gastado += b.total;
  });
  const list = Object.values(map).sort((a, b) => b.reservas - a.reservas);
  const waLink = (phone) => `https://wa.me/51${phone}`;

  return (
    <div className="stack">
      <div className="kpis">
        <div className="kpi">
          <div className="lab"><Users size={13} /> Jugadores registrados</div>
          <div className="num">{list.length}</div>
          <div className="foot">Base de datos del club</div>
        </div>
        <div className="kpi">
          <div className="lab"><CalendarDays size={13} /> Reservas totales</div>
          <div className="num">{list.reduce((s, c) => s + c.reservas, 0)}</div>
          <div className="foot mut" style={{ color: "var(--mut)" }}>Histórico</div>
        </div>
      </div>

      <div className="card pad">
        <div className="sm" style={{ fontWeight: 700, marginBottom: 4 }}>Lista de jugadores</div>
        {list.length === 0 && <div className="mut sm">Aún no hay jugadores registrados. Se agregan solos cuando entran por el link.</div>}
        {list.map((c) => (
          <div className="row" key={c.phone}>
            <div style={{ width: 42, height: 42, borderRadius: 999, background: "var(--surf2)", display: "grid", placeItems: "center", fontFamily: "Sora", fontWeight: 800, color: "var(--turf)" }}>
              {c.nombres.slice(0, 1).toUpperCase()}
            </div>
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ fontWeight: 600, fontSize: 14 }}>{c.nombres}</div>
              <div className="xs mut mono">{c.phone}</div>
            </div>
            <div style={{ textAlign: "right" }}>
              <div className="mono" style={{ fontWeight: 700, fontSize: 15 }}>{c.reservas}</div>
              <div className="xs mut">reservas</div>
            </div>
            <a className="btn-ghost" href={waLink(c.phone)} target="_blank" rel="noreferrer"
               style={{ display: "flex", alignItems: "center", gap: 6, textDecoration: "none", color: "#7CE9A0", background: "rgba(37,211,102,.14)", borderColor: "rgba(37,211,102,.4)" }}>
              <MessageCircle size={14} />
            </a>
          </div>
        ))}
      </div>
    </div>
  );
}

function Resumen({ bookings, products, clients, sales, expenses, setExpenses }) {
  const today = todayISO();
  const monthPrefix = today.slice(0, 7); // "YYYY-MM"
  const isToday = (ts) => new Date(ts).toISOString().slice(0, 10) === today;
  const isThisMonth = (ts) => new Date(ts).toISOString().slice(0, 7) === monthPrefix;

  const confirmed = bookings.filter((b) => b.status === "confirmado");
  const confirmedToday = confirmed.filter((b) => b.date === today);
  const confirmedMonth = confirmed.filter((b) => b.date.slice(0, 7) === monthPrefix);
  const todayBookings = bookings.filter((b) => b.date === today);

  const courtToday = confirmedToday.reduce((s, b) => s + b.total, 0);
  const courtMonth = confirmedMonth.reduce((s, b) => s + b.total, 0);

  const salesToday = sales.filter((s) => isToday(s.ts));
  const salesMonth = sales.filter((s) => isThisMonth(s.ts));
  const kioskToday = salesToday.reduce((s, v) => s + v.total, 0);
  const kioskMonth = salesMonth.reduce((s, v) => s + v.total, 0);

  const ingresosHoy = courtToday + kioskToday;
  const ingresosMes = courtMonth + kioskMonth;

  const expensesToday = expenses.filter((e) => isToday(e.ts));
  const gastosHoy = expensesToday.reduce((s, e) => s + e.monto, 0);
  const utilidadHoy = ingresosHoy - gastosHoy;

  const horasJugadasHoy = confirmedToday.reduce((s, b) => s + b.hours.length, 0);
  const totalSlotsHoy = HOURS.length * COURTS.length;
  const occPct = Math.round((horasJugadasHoy / totalSlotsHoy) * 100) || 0;

  const productosVendidosHoy = salesToday.reduce((s, v) => s + v.items.reduce((a, i) => a + i.qty, 0), 0);

  const clientesNuevosHoy = clients.filter((c) => c.joinedAt && isToday(c.joinedAt)).length;
  const clientesNuevosMes = clients.filter((c) => c.joinedAt && isThisMonth(c.joinedAt)).length;

  const confirmedTodayCount = todayBookings.filter((b) => b.status === "confirmado").length;
  const pend = bookings.filter((b) => b.status === "pendiente").length;
  const low = products.filter((p) => p.stock <= p.min);

  // Horas más alquiladas (histórico, solo confirmadas)
  const hourCounts = {};
  confirmed.forEach((b) => b.hours.forEach((h) => { hourCounts[h] = (hourCounts[h] || 0) + 1; }));
  const topHours = Object.entries(hourCounts).sort((a, b) => b[1] - a[1]).slice(0, 3);

  // Días con mayor demanda
  const dayCounts = {};
  confirmed.forEach((b) => { const l = weekdayLabel(b.date); dayCounts[l] = (dayCounts[l] || 0) + 1; });
  const topDays = Object.entries(dayCounts).sort((a, b) => b[1] - a[1]).slice(0, 3);

  // Clientes frecuentes
  const freqMap = {};
  bookings.forEach((b) => {
    if (!b.phone) return;
    if (!freqMap[b.phone]) freqMap[b.phone] = { nombre: b.client, reservas: 0 };
    freqMap[b.phone].reservas += 1;
  });
  const topClients = Object.values(freqMap).sort((a, b) => b.reservas - a.reservas).slice(0, 5);

  // Serie real de los últimos 7 días (ingresos vs gastos)
  const last7 = Array.from({ length: 7 }, (_, i) => {
    const d = new Date(); d.setDate(d.getDate() - (6 - i)); return d.toISOString().slice(0, 10);
  });
  const weekReal = last7.map((iso) => {
    const ing = confirmed.filter((b) => b.date === iso).reduce((s, b) => s + b.total, 0)
      + sales.filter((s) => new Date(s.ts).toISOString().slice(0, 10) === iso).reduce((s, v) => s + v.total, 0);
    const gas = expenses.filter((e) => new Date(e.ts).toISOString().slice(0, 10) === iso).reduce((s, e) => s + e.monto, 0);
    return { d: weekdayLabel(iso), ingresos: ing, gastos: gas };
  });

  const [concepto, setConcepto] = useState("");
  const [monto, setMonto] = useState("");
  const addExpense = () => {
    const n = parseFloat(monto);
    if (!concepto.trim() || !n || n <= 0) return;
    setExpenses((e) => [{ id: uid(), concepto: concepto.trim(), monto: n, ts: Date.now(), tipo: "manual" }, ...e]);
    setConcepto(""); setMonto("");
  };

  return (
    <div className="stack">
      {/* 1) Tarjetas de resumen */}
      <div className="kpis">
        <div className="kpi">
          <div className="lab"><Wallet size={13} /> Ingresos del día</div>
          <div className="num">{money(ingresosHoy)}</div>
          <div className="foot">Cancha {money(courtToday)} · Kiosco {money(kioskToday)}</div>
        </div>
        <div className="kpi">
          <div className="lab"><TrendingUp size={13} /> Ingresos del mes</div>
          <div className="num">{money(ingresosMes)}</div>
          <div className="foot">Cancha {money(courtMonth)} · Kiosco {money(kioskMonth)}</div>
        </div>
        <div className="kpi">
          <div className="lab"><CalendarDays size={13} /> Total de reservas</div>
          <div className="num">{todayBookings.length}</div>
          <div className="foot">{confirmedTodayCount} confirmadas hoy</div>
        </div>
        <div className="kpi">
          <div className="lab"><Clock size={13} /> Horas jugadas</div>
          <div className="num">{horasJugadasHoy}</div>
          <div className="foot">{occPct}% de ocupación hoy</div>
        </div>
        <div className="kpi">
          <div className="lab"><ShoppingBasket size={13} /> Productos vendidos</div>
          <div className="num">{productosVendidosHoy}</div>
          <div className="foot">{money(kioskToday)} en ventas hoy</div>
        </div>
        <div className="kpi">
          <div className="lab"><Users size={13} /> Clientes nuevos</div>
          <div className="num">{clientesNuevosHoy}</div>
          <div className="foot">{clientesNuevosMes} este mes</div>
        </div>
      </div>

      {pend > 0 && (
        <div className="alertbar" style={{ borderColor: "var(--amber)" }}>
          <Smartphone size={18} color="var(--amber)" />
          <div className="sm"><b>{pend} Yape{pend > 1 ? "s" : ""} por confirmar.</b> <span className="mut">Revisa la pestaña Reservas.</span></div>
        </div>
      )}

      {low.length > 0 && (
        <div className="alertbar">
          <AlertTriangle size={18} color="var(--danger)" />
          <div className="sm">
            <b>{low.length} producto{low.length > 1 ? "s" : ""} por agotarse:</b>{" "}
            <span className="mut">{low.map((p) => `${p.name} (${p.stock})`).join(" · ")}</span>
          </div>
        </div>
      )}

      {/* 2) Ganancias separadas */}
      <div className="card pad">
        <div className="sm" style={{ fontWeight: 700, marginBottom: 12 }}>Ganancias separadas · este mes</div>
        <div style={{ display: "flex", justifyContent: "space-between" }}>
          <div><div className="xs mut">Cancha (alquiler)</div><div className="mono" style={{ fontWeight: 700, fontSize: 20, color: "var(--turf)" }}>{money(courtMonth)}</div></div>
          <div><div className="xs mut">Kiosco (productos)</div><div className="mono" style={{ fontWeight: 700, fontSize: 20, color: "var(--amber)" }}>{money(kioskMonth)}</div></div>
          <div><div className="xs mut">Total combinado</div><div className="mono" style={{ fontWeight: 800, fontSize: 20 }}>{money(ingresosMes)}</div></div>
        </div>
        <div style={{ display: "flex", height: 8, borderRadius: 6, overflow: "hidden", marginTop: 14, background: "var(--surf2)" }}>
          <div style={{ width: `${ingresosMes ? (courtMonth / ingresosMes) * 100 : 50}%`, background: "var(--turf)" }} />
          <div style={{ width: `${ingresosMes ? (kioskMonth / ingresosMes) * 100 : 50}%`, background: "var(--amber)" }} />
        </div>
      </div>

      {/* 3) Caja diaria */}
      <div className="card pad">
        <div className="sm" style={{ fontWeight: 700, marginBottom: 12 }}>Caja diaria · hoy</div>
        <div style={{ display: "flex", justifyContent: "space-between" }}>
          <div><div className="xs mut">Ingresos totales</div><div className="mono" style={{ fontWeight: 700, fontSize: 20, color: "var(--turf)" }}>{money(ingresosHoy)}</div></div>
          <div><div className="xs mut">Egresos</div><div className="mono" style={{ fontWeight: 700, fontSize: 20, color: "var(--danger)" }}>{money(gastosHoy)}</div></div>
          <div><div className="xs mut">Utilidad</div><div className="mono" style={{ fontWeight: 800, fontSize: 20, color: utilidadHoy >= 0 ? "var(--turf)" : "var(--danger)" }}>{money(utilidadHoy)}</div></div>
        </div>
        <div className="divider" />
        <div className="sm" style={{ fontWeight: 600, margin: "10px 0 8px" }}>Agregar gasto</div>
        <div style={{ display: "flex", gap: 8 }}>
          <input className="input" placeholder="Concepto (ej. luz, personal)" value={concepto} onChange={(e) => setConcepto(e.target.value)} style={{ flex: 2 }} />
          <input className="input" type="number" placeholder="Monto" value={monto} onChange={(e) => setMonto(e.target.value)} style={{ flex: 1 }} />
          <button className="btn btn-ghost" onClick={addExpense}><Plus size={14} /></button>
        </div>
        {expensesToday.length > 0 && (
          <div style={{ marginTop: 10 }}>
            {expensesToday.slice(0, 5).map((e) => (
              <div className="row" key={e.id}>
                <div style={{ flex: 1, fontSize: 13 }}>{e.concepto}</div>
                <div className="mono xs mut">{money(e.monto)}</div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* 4) Estadísticas */}
      <div className="card pad">
        <div className="sm" style={{ fontWeight: 700, marginBottom: 12 }}>Estadísticas</div>

        <div className="xs mut" style={{ marginBottom: 6 }}>Horas más alquiladas</div>
        {topHours.length === 0
          ? <div className="xs mut" style={{ marginBottom: 12 }}>Aún no hay datos suficientes.</div>
          : topHours.map(([h, c]) => (
            <div className="row" key={h}>
              <div style={{ flex: 1, fontSize: 13 }}>{hourAP(Number(h))}</div>
              <div className="mono xs" style={{ color: "var(--turf)" }}>{c} reserva{c > 1 ? "s" : ""}</div>
            </div>
          ))}

        <div className="divider" />
        <div className="xs mut" style={{ margin: "10px 0 6px" }}>Días con mayor demanda</div>
        {topDays.length === 0
          ? <div className="xs mut" style={{ marginBottom: 12 }}>Aún no hay datos suficientes.</div>
          : topDays.map(([d, c]) => (
            <div className="row" key={d}>
              <div style={{ flex: 1, fontSize: 13 }}>{d}</div>
              <div className="mono xs" style={{ color: "var(--turf)" }}>{c} reserva{c > 1 ? "s" : ""}</div>
            </div>
          ))}

        <div className="divider" />
        <div className="xs mut" style={{ margin: "10px 0 6px" }}>Clientes frecuentes</div>
        {topClients.length === 0
          ? <div className="xs mut" style={{ marginBottom: 12 }}>Aún no hay clientes con reservas.</div>
          : topClients.map((c, i) => (
            <div className="row" key={i}>
              <div style={{ flex: 1, fontSize: 13 }}>{c.nombre}</div>
              <div className="mono xs" style={{ color: "var(--turf)" }}>{c.reservas} reserva{c.reservas > 1 ? "s" : ""}</div>
            </div>
          ))}

        <div className="divider" />
        <div style={{ display: "flex", justifyContent: "space-between", marginTop: 10 }}>
          <div className="xs mut">Total de clientes nuevos · este mes</div>
          <div className="mono" style={{ fontWeight: 700 }}>{clientesNuevosMes}</div>
        </div>
      </div>

      {/* Gráfica semanal real */}
      <div className="card pad">
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
          <span className="sm" style={{ fontWeight: 700 }}>Ingresos vs gastos · últimos 7 días</span>
          <span className="badge-live"><span className="dot" /> En vivo</span>
        </div>
        <div style={{ width: "100%", height: 190 }}>
          <ResponsiveContainer>
            <BarChart data={weekReal} barGap={4}>
              <CartesianGrid strokeDasharray="3 3" stroke="#E5E7EB" vertical={false} />
              <XAxis dataKey="d" stroke="#64748B" fontSize={11} tickLine={false} axisLine={false} />
              <YAxis stroke="#64748B" fontSize={11} tickLine={false} axisLine={false} width={30} />
              <Tooltip contentStyle={{ background: "#FFFFFF", border: "1px solid #E5E7EB", borderRadius: 10, color: "#1E293B" }}
                formatter={(v, n) => [money(v), n === "ingresos" ? "Ingresos" : "Gastos"]} />
              <Bar dataKey="ingresos" fill="#0060F8" radius={[5, 5, 0, 0]} />
              <Bar dataKey="gastos" fill="#F5B400" radius={[5, 5, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
}

function Reservas({ bookings, setBookings, prices, authLevel }) {
  const isOwner = authLevel === "owner";
  const confirm = (id) => setBookings((p) => p.map((b) => (b.id === id ? { ...b, status: "confirmado" } : b)));
  const reject = (b) => {
    if (!window.confirm(`¿Rechazar el Yape de ${b.client}? La hora queda libre otra vez.`)) return;
    setBookings((p) => p.filter((x) => x.id !== b.id));
  };
  const noShow = (id) => setBookings((p) => p.map((b) => (b.id === id ? { ...b, status: "no_show" } : b)));
  const removeBooking = (b) => {
    if (!window.confirm(`¿Eliminar la reserva de ${b.client} (${courtName(b.courtId)} · ${b.hours.map(hourAP).join(", ")})? Esto no se puede deshacer.`)) return;
    setBookings((p) => p.filter((x) => x.id !== b.id));
  };

  const today = bookings.filter((b) => b.date === todayISO());
  // Ojo: los clientes pueden reservar hasta 6 días adelante, así que los Yapes
  // por confirmar se buscan en TODAS las reservas, no solo las de hoy — si no,
  // un pago de mañana nunca aparecería aquí para revisarlo.
  const pend = bookings.filter((b) => b.status === "pendiente");

  // Avisos WhatsApp: horas prime (noche) aún libres para hoy
  const primeFree = [];
  COURTS.forEach((c) => {
    const relevant = blockingCourts(c.id);
    HOURS.filter((h) => h >= prices.nightStart).forEach((h) => {
      const taken = bookings.some((b) => relevant.includes(b.courtId) && b.date === todayISO() && b.status !== "no_show" && b.hours.includes(h));
      if (!taken) primeFree.push({ court: c.name, h });
    });
  });

  const [sent, setSent] = useState(false);

  const courtName = (id) => COURTS.find((c) => c.id === id)?.name || id;

  return (
    <div className="stack">
      {pend.length > 0 && (
        <div className="card pad">
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 6 }}>
            <Smartphone size={16} color="var(--amber)" />
            <span className="sm" style={{ fontWeight: 700 }}>Yapes por confirmar</span>
            <span className="pill pend" style={{ marginLeft: "auto" }}>{pend.length}</span>
          </div>
          <div className="xs mut" style={{ marginBottom: 6 }}>Confirma cuando te llegue el Yape al celular. Al aprobar, la hora queda bloqueada.</div>
          {pend.map((b) => (
            <div className="row" key={b.id} style={{ flexWrap: "wrap" }}>
              {b.paymentProof ? (
                <a href={b.paymentProof} target="_blank" rel="noopener noreferrer" title="Ver captura completa">
                  <img
                    src={b.paymentProof} alt="Comprobante Yape"
                    style={{ width: 52, height: 52, objectFit: "cover", borderRadius: 10, border: "1px solid var(--line)", flex: "none" }}
                  />
                </a>
              ) : (
                <div style={{ width: 52, height: 52, borderRadius: 10, border: "1px dashed var(--line)", display: "grid", placeItems: "center", flex: "none" }}>
                  <Smartphone size={18} color="var(--mut)" />
                </div>
              )}
              <div style={{ flex: 1, minWidth: 140 }}>
                <div style={{ fontWeight: 600, fontSize: 14 }}>{b.client}</div>
                <div className="xs mut">{b.phone}</div>
                <div className="xs mut">{courtName(b.courtId)} · {dayLabel(b.date)} · {b.hours.map(hourAP).join(", ")}</div>
                <div className="xs" style={{ color: "var(--amber)", marginTop: 2 }}>Separación {money(b.deposit ?? 0)} · Falta {money(b.restante ?? b.total)}</div>
              </div>
              <button className="btn-danger" title="Rechazar" onClick={() => reject(b)}><X size={15} /></button>
              <button className="btn btn-turf" style={{ padding: "9px 14px", fontSize: 13 }} onClick={() => confirm(b.id)}>
                <Check size={15} /> Confirmar
              </button>
            </div>
          ))}
        </div>
      )}

      {/* Avisos WhatsApp */}
      <div className="wa">
        <MessageCircle size={20} color="#25D366" />
        <div style={{ flex: 1 }}>
          <div className="sm" style={{ fontWeight: 700 }}>Avisar horas libres por WhatsApp</div>
          <div className="xs mut">
            {primeFree.length
              ? `${primeFree.length} horas noche siguen libres hoy. Avisa a clientes frecuentes 3 h antes.`
              : "Todas las horas noche de hoy están tomadas. 🔥"}
          </div>
        </div>
        {primeFree.length > 0 && (
          <button className="btn btn-ghost" style={{ background: "rgba(37,211,102,.14)", borderColor: "rgba(37,211,102,.4)", color: "#7CE9A0" }} onClick={() => setSent(true)}>
            {sent ? "Enviado ✓" : "Enviar"}
          </button>
        )}
      </div>

      {/* Ocupación de hoy */}
      <div className="card pad">
        <div className="sm" style={{ fontWeight: 700, marginBottom: 10 }}>Reservas de hoy · {dayLabel(todayISO())}</div>
        {today.length === 0 && <div className="mut sm">Aún no hay reservas para hoy.</div>}
        {today.map((b) => (
          <div className="row" key={b.id}>
            <div style={{ width: 40, height: 40, borderRadius: 10, background: "var(--surf2)", display: "grid", placeItems: "center" }}>
              <CircleDot size={18} />
            </div>
            <div style={{ flex: 1 }}>
              <div style={{ fontWeight: 600, fontSize: 14 }}>{courtName(b.courtId)} · <span className="mono">{b.hours.map(hourAP).join(", ")}</span></div>
              <div className="xs mut">{b.client} · {money(b.total)}</div>
            </div>
            <span className={`pill ${b.status === "confirmado" ? "ok" : b.status === "pendiente" ? "pend" : "ns"}`}>
              {b.status === "confirmado" ? "Pagado" : b.status === "pendiente" ? "Pendiente" : "No llegó"}
            </span>
            {b.status === "confirmado" && (
              <button className="btn-danger xs" style={{ padding: "6px 9px" }} onClick={() => noShow(b.id)}>No llegó</button>
            )}
            {isOwner && (
              <button className="btn-danger xs" style={{ padding: "6px 9px" }} title="Eliminar reserva" onClick={() => removeBooking(b)}>
                <Trash2 size={13} />
              </button>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

const SCAN_FORMATS = [
  Html5QrcodeSupportedFormats.CODE_128,
  Html5QrcodeSupportedFormats.CODE_39,
  Html5QrcodeSupportedFormats.CODE_93,
  Html5QrcodeSupportedFormats.EAN_13,
  Html5QrcodeSupportedFormats.EAN_8,
  Html5QrcodeSupportedFormats.UPC_A,
  Html5QrcodeSupportedFormats.UPC_E,
  Html5QrcodeSupportedFormats.ITF,
  Html5QrcodeSupportedFormats.QR_CODE,
];

// Detiene la cámara sin tirar abajo la app: start()/stop() de html5-qrcode
// pueden lanzar de forma síncrona o dejar promesas sin resolver si se llaman
// fuera de orden (p.ej. al desmontar justo después de detectar un código).
async function safeStopScanner(inst) {
  if (!inst) return;
  try {
    if (typeof inst.getState === "function") {
      const state = inst.getState();
      if (state !== Html5QrcodeScannerState.SCANNING && state !== Html5QrcodeScannerState.PAUSED) return;
    }
  } catch (e) { /* ignorar */ }
  try { await inst.stop(); } catch (e) { /* ignorar */ }
  try { inst.clear(); } catch (e) { /* ignorar */ }
}

function Scanner({ products, setProducts, onDetect, onClose }) {
  const regionId = useRef(`scanner-region-${uid()}`);
  const html5QrRef = useRef(null);
  const detectedRef = useRef(false);
  const mountedRef = useRef(true);
  const [manual, setManual] = useState("");
  const [camState, setCamState] = useState("starting"); // starting | live | denied | unsupported
  const [newCode, setNewCode] = useState(null); // código escaneado que no existe aún
  const [name, setName] = useState("");
  const [price, setPrice] = useState("");
  const [cost, setCost] = useState("");
  const [stock, setStock] = useState("");
  const [msg, setMsg] = useState("");

  const handleCodeRef = useRef();
  handleCodeRef.current = (code) => {
    const clean = String(code || "").trim();
    if (!clean) { detectedRef.current = false; return; }
    const p = products.find((x) => x.barcode === clean);
    if (p) {
      onDetect(p, { isNew: false });
      // Deja el escáner "armado" para el siguiente producto (p.ej. varias
      // ventas seguidas en el kiosco); la pausa evita que el mismo código,
      // si sigue en cuadro, se vuelva a leer de inmediato.
      setTimeout(() => { detectedRef.current = false; }, 1200);
      return;
    }
    setNewCode(clean);
    setName(""); setPrice(""); setCost(""); setStock("");
    setMsg("");
    try { html5QrRef.current && html5QrRef.current.pause(true); } catch (e) { /* ignorar */ }
  };

  useEffect(() => {
    mountedRef.current = true;
    let cancelled = false;

    async function start() {
      if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        setCamState("unsupported");
        return;
      }
      try {
        const inst = new Html5Qrcode(regionId.current, { formatsToSupport: SCAN_FORMATS, verbose: false });
        html5QrRef.current = inst;
        await inst.start(
          { facingMode: "environment" },
          {
            fps: 10,
            // Función en vez de tamaño fijo: se adapta al ancho real del visor
            // en cada celular, evitando el error de html5-qrcode cuando el
            // recuadro pedido es más grande que la cámara disponible.
            qrbox: (viewfinderWidth, viewfinderHeight) => {
              const edge = Math.floor(Math.min(viewfinderWidth, viewfinderHeight * 1.8) * 0.72);
              const width = Math.max(180, Math.min(edge, 280));
              return { width, height: Math.round(width * 0.52) };
            },
            disableFlip: true,
            experimentalFeatures: { useBarCodeDetectorIfSupported: true },
          },
          (decodedText) => {
            if (!mountedRef.current || detectedRef.current) return;
            detectedRef.current = true;
            handleCodeRef.current(decodedText);
          },
          () => { /* fallo de lectura en un frame: normal, se ignora */ }
        );
        if (cancelled) { safeStopScanner(inst); return; }
        setCamState("live");
      } catch (e) {
        if (!cancelled) setCamState("denied");
      }
    }
    start();

    return () => {
      cancelled = true;
      mountedRef.current = false;
      safeStopScanner(html5QrRef.current);
    };
  }, []);

  const resumeScanning = () => {
    setNewCode(null);
    detectedRef.current = false;
    try {
      const inst = html5QrRef.current;
      if (inst && inst.getState && inst.getState() === Html5QrcodeScannerState.PAUSED) inst.resume();
    } catch (e) { /* ignorar */ }
  };

  const submitRegister = () => {
    const nm = name.trim();
    const pr = Number(price);
    if (!nm) { setMsg("Escribe el nombre del producto."); return; }
    if (!pr || pr <= 0) { setMsg("Escribe un precio de venta válido."); return; }
    const product = {
      id: uid(),
      name: nm,
      barcode: newCode,
      price: pr,
      cost: Math.max(0, Number(cost) || 0),
      stock: Math.max(0, parseInt(stock, 10) || 0),
      min: 3,
    };
    setProducts((ps) => [...ps, product]);
    onDetect(product, { isNew: true });
    // Si el que llama no cierra el escáner (p.ej. quedó sin stock), vuelve a
    // dejarlo listo para leer el siguiente código en vez de quedarse trabado.
    resumeScanning();
  };

  const finishManual = () => {
    if (!manual.trim()) return;
    detectedRef.current = true;
    handleCodeRef.current(manual);
  };

  return (
    <div className="overlay" onClick={onClose}>
      <div className="modal" onClick={(e) => e.stopPropagation()}>
        <div className="modal-top">
          <span style={{ display: "flex", alignItems: "center", gap: 8, fontWeight: 700 }}><ScanLine size={16} color="var(--turf)" /> Leer código de barras</span>
          <button className="btn-ghost" style={{ padding: 8, borderRadius: 10 }} onClick={onClose}><X size={16} /></button>
        </div>
        <div className="pad">
          {/* El div de la cámara nunca se desmonta ni se oculta con display:none:
              html5-qrcode mide su ancho/alto al iniciar y sigue dueño de ese nodo
              mientras la instancia esté viva (aunque esté en pausa). Ocultarlo o
              quitarlo del DOM aquí dejaría la cámara prendida "por detrás" sin
              que la librería lo sepa. Por eso el estado "starting/denied" y el
              formulario de producto nuevo se dibujan como capas encima, y lo de
              abajo (código manual vs. registrar producto) es lo único que cambia. */}
          <div className="scanner">
            <div
              id={regionId.current}
              style={{ position: "absolute", inset: 0, width: "100%", height: "100%" }}
            />
            {camState === "live" && !newCode && <div className="scan-frame" />}
            {camState !== "live" && (
              <div style={{ position: "absolute", inset: 0, display: "grid", placeItems: "center", background: "#0F172A" }}>
                {camState === "starting" && (
                  <div style={{ textAlign: "center" }}>
                    <Camera size={30} color="var(--mut)" />
                    <div className="xs mut" style={{ marginTop: 8 }}>Abriendo cámara…</div>
                  </div>
                )}
                {(camState === "denied" || camState === "unsupported") && (
                  <div style={{ textAlign: "center", padding: "0 20px" }}>
                    <CameraOff size={30} color="var(--amber)" />
                    <div className="xs mut" style={{ marginTop: 8, lineHeight: 1.5 }}>
                      {camState === "denied"
                        ? "No se pudo abrir la cámara aquí. En el sitio publicado con https funciona; da permiso de cámara al navegador."
                        : "Este visor no permite cámara. Funcionará en el sitio publicado. Usa el código manual por ahora."}
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>

          {newCode ? (
            <div style={{ marginTop: 12 }}>
              <div className="wa" style={{ borderColor: "var(--amber)", background: "rgba(245,180,0,.08)", marginBottom: 12 }}>
                <AlertTriangle size={16} color="var(--amber)" />
                <span className="sm">Producto nuevo. Regístralo para que la próxima vez se reconozca solo.</span>
              </div>
              <span className="field-lab">Código de barras</span>
              <input className="input" value={newCode} disabled style={{ opacity: 0.7, marginBottom: 12 }} />
              <span className="field-lab">Nombre del producto</span>
              <input className="input" placeholder="Ej. Coca-Cola 500ml" value={name} onChange={(e) => setName(e.target.value)} style={{ marginBottom: 12 }} autoFocus />
              <span className="field-lab">Precio de venta</span>
              <input className="input" type="number" placeholder="4" value={price} onChange={(e) => setPrice(e.target.value)} style={{ marginBottom: 12 }} />
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
                <div>
                  <span className="field-lab">Costo (opcional)</span>
                  <input className="input" type="number" placeholder="2.6" value={cost} onChange={(e) => setCost(e.target.value)} />
                </div>
                <div>
                  <span className="field-lab">Stock inicial</span>
                  <input className="input" type="number" placeholder="0" value={stock} onChange={(e) => setStock(e.target.value)} />
                </div>
              </div>
              {msg && <div className="xs" style={{ color: "var(--danger)", margin: "10px 0 0" }}>{msg}</div>}
              <div style={{ display: "flex", gap: 8, marginTop: 14 }}>
                <button className="btn btn-ghost" onClick={resumeScanning}>Cancelar</button>
                <button className="btn btn-turf block" onClick={submitRegister}><Check size={17} /> Guardar y continuar</button>
              </div>
            </div>
          ) : (
            <>
              <div className="xs mut" style={{ textAlign: "center", margin: "10px 0" }}>
                {camState === "live" ? "Apunta al código de barras, se reconoce solo" : "Ingresa el código para continuar"}
              </div>
              <span className="field-lab">Código de barras</span>
              <div style={{ display: "flex", gap: 8 }}>
                <input className="input" placeholder="7750182001234" value={manual} onChange={(e) => setManual(e.target.value)} />
                <button className="btn btn-turf" onClick={finishManual}>Buscar</button>
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

function Quiosco({ products, setProducts, sales, setSales }) {
  const [cart, setCart] = useState([]);
  const [scan, setScan] = useState(false);
  const [msg, setMsg] = useState("");

  const addToCart = (p) => {
    if (!p) { setMsg("Código no encontrado en inventario."); setTimeout(() => setMsg(""), 2200); return; }
    if (p.stock <= 0) { setMsg(`${p.name} sin stock.`); setTimeout(() => setMsg(""), 2200); return; }
    setCart((c) => {
      const ex = c.find((i) => i.id === p.id);
      if (ex) return c.map((i) => (i.id === p.id ? { ...i, qty: Math.min(i.qty + 1, p.stock) } : i));
      return [...c, { id: p.id, name: p.name, price: p.price, qty: 1 }];
    });
    setScan(false);
  };
  const setQty = (id, d) => setCart((c) => c.map((i) => (i.id === id ? { ...i, qty: Math.max(1, i.qty + d) } : i)));
  const remove = (id) => setCart((c) => c.filter((i) => i.id !== id));

  const total = cart.reduce((s, i) => s + i.price * i.qty, 0);

  const checkout = () => {
    setProducts((ps) => ps.map((p) => {
      const inCart = cart.find((i) => i.id === p.id);
      return inCart ? { ...p, stock: Math.max(0, p.stock - inCart.qty) } : p;
    }));
    setSales((s) => [{ id: uid(), items: cart, total, ts: Date.now() }, ...s]);
    setCart([]);
    setMsg(`Venta registrada: ${money(total)}`);
    setTimeout(() => setMsg(""), 2500);
  };

  return (
    <div className="stack">
      <button className="btn btn-turf block" onClick={() => setScan(true)} style={{ fontSize: 16 }}>
        <ScanLine size={20} /> Escanear producto para vender
      </button>

      {msg && <div className="wa" style={{ borderColor: "var(--turf)", background: "rgba(0,96,248,.08)" }}><Check size={16} color="var(--turf)" /><span className="sm">{msg}</span></div>}

      {/* Acceso rápido productos */}
      <div className="card pad">
        <div className="sm" style={{ fontWeight: 700, marginBottom: 10 }}>Venta rápida</div>
        <div className="seg">
          {products.map((p) => (
            <button key={p.id} className="chip" onClick={() => addToCart(p)} disabled={p.stock <= 0} style={{ opacity: p.stock <= 0 ? 0.4 : 1 }}>
              {p.name.split(" ")[0]} <span className="mono mut">{money(p.price)}</span>
            </button>
          ))}
        </div>
      </div>

      {/* Carrito */}
      {cart.length > 0 && (
        <div className="card pad">
          <div className="sm" style={{ fontWeight: 700, marginBottom: 4 }}>Venta actual</div>
          {cart.map((i) => (
            <div className="row" key={i.id}>
              <div style={{ flex: 1 }}>
                <div style={{ fontWeight: 600, fontSize: 14 }}>{i.name}</div>
                <div className="xs mut mono">{money(i.price)} c/u</div>
              </div>
              <div className="qty">
                <button onClick={() => setQty(i.id, -1)}><Minus size={14} /></button>
                <span className="n">{i.qty}</span>
                <button onClick={() => setQty(i.id, 1)}><Plus size={14} /></button>
              </div>
              <div className="mono" style={{ fontWeight: 700, minWidth: 52, textAlign: "right" }}>{money(i.price * i.qty)}</div>
              <button className="btn-danger" style={{ padding: 8 }} onClick={() => remove(i.id)}><Trash2 size={14} /></button>
            </div>
          ))}
          <div className="divider" />
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <div><div className="xs mut">Total</div><div className="mono" style={{ fontWeight: 700, fontSize: 24, color: "var(--turf)" }}>{money(total)}</div></div>
            <button className="btn btn-turf" onClick={checkout}><Check size={18} /> Cobrar venta</button>
          </div>
        </div>
      )}

      {scan && <Scanner products={products} setProducts={setProducts} onDetect={addToCart} onClose={() => setScan(false)} />}
    </div>
  );
}

function Inventario({ products, setProducts, setExpenses }) {
  const [scan, setScan] = useState(false);
  const [restockId, setRestockId] = useState(null);
  const [qty, setQty] = useState("");

  const doRestock = (p) => { setRestockId(p.id); setScan(false); };
  const confirmRestock = () => {
    const n = parseInt(qty, 10);
    if (!n || n <= 0 || n > 9999) return;
    const p = products.find((x) => x.id === restockId);
    setProducts((ps) => ps.map((x) => (x.id === restockId ? { ...x, stock: x.stock + n } : x)));
    setExpenses((e) => [
      { id: uid(), concepto: `Reposición: ${p?.name || "producto"} x${n}`, monto: n * (p?.cost || 0), ts: Date.now(), tipo: "inventario" },
      ...e,
    ]);
    setRestockId(null); setQty("");
  };

  const sorted = [...products].sort((a, b) => (a.stock <= a.min ? -1 : 1) - (b.stock <= b.min ? -1 : 1));

  return (
    <div className="stack">
      <button className="btn btn-amber block" onClick={() => setScan(true)}>
        <ScanLine size={19} /> Escanear para agregar stock
      </button>

      <div className="card pad">
        <div className="sm" style={{ fontWeight: 700, marginBottom: 4 }}>Inventario del quiosco</div>
        {sorted.map((p) => {
          const low = p.stock <= p.min;
          return (
            <div className="row" key={p.id}>
              <div style={{ flex: 1 }}>
                <div style={{ fontWeight: 600, fontSize: 14, display: "flex", alignItems: "center", gap: 8 }}>
                  {p.name}
                  {low && <span className="pill ns"><AlertTriangle size={10} style={{ marginRight: 3 }} />Reponer</span>}
                </div>
                <div className="xs mut mono">{p.barcode} · vende {money(p.price)}</div>
              </div>
              <div style={{ textAlign: "right" }}>
                <div className="mono" style={{ fontWeight: 700, fontSize: 18, color: low ? "var(--danger)" : "var(--turf)" }}>{p.stock}</div>
                <div className="xs mut">min {p.min}</div>
              </div>
              <button className="btn btn-ghost" onClick={() => doRestock(p)}><Plus size={14} /> Stock</button>
            </div>
          );
        })}
      </div>

      {scan && (
        <Scanner
          products={products}
          setProducts={setProducts}
          onDetect={(p, meta) => {
            if (!p) return;
            if (meta?.isNew) setScan(false);
            else doRestock(p);
          }}
          onClose={() => setScan(false)}
        />
      )}

      {restockId && (
        <div className="overlay" onClick={() => setRestockId(null)}>
          <div className="modal" onClick={(e) => e.stopPropagation()}>
            <div className="modal-top">
              <span style={{ fontWeight: 700 }}>Agregar stock</span>
              <button className="btn-ghost" style={{ padding: 8, borderRadius: 10 }} onClick={() => setRestockId(null)}><X size={16} /></button>
            </div>
            <div className="pad">
              <div className="sm" style={{ fontWeight: 600, marginBottom: 12 }}>{products.find((p) => p.id === restockId)?.name}</div>
              <span className="field-lab">¿Cuántas unidades llegaron?</span>
              <input className="input" type="number" placeholder="12" value={qty} onChange={(e) => setQty(e.target.value)} autoFocus />
              <div className="xs mut" style={{ margin: "8px 0 14px" }}>Se sumará al stock y registrará el gasto de compra.</div>
              <button className="btn btn-turf block" onClick={confirmRestock}><Check size={17} /> Agregar al inventario</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function PriceField({ label, value, onChange, suffix = "S/" }) {
  return (
    <div>
      <span className="field-lab">{label}</span>
      <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
        <span className="mono mut" style={{ fontSize: 15 }}>{suffix}</span>
        <input className="input" type="number" value={value} onChange={(e) => onChange(e.target.value)} />
      </div>
    </div>
  );
}

function Precios({ prices, setPrices, settings, setSettings }) {
  const upd = (path, val) => {
    const n = Number(val);
    setPrices((p) => {
      const c = JSON.parse(JSON.stringify(p));
      if (path.length === 2) c[path[0]][path[1]] = n; else c[path[0]] = n;
      return c;
    });
  };
  const Field = PriceField;

  const [qrErr, setQrErr] = useState("");
  const onQrFile = (e) => {
    const file = e.target.files?.[0];
    e.target.value = "";
    if (!file) return;
    if (!file.type.startsWith("image/")) { setQrErr("Elige una imagen (PNG o JPG)."); return; }
    if (file.size > 2 * 1024 * 1024) { setQrErr("La imagen debe pesar menos de 2 MB."); return; }
    setQrErr("");
    const reader = new FileReader();
    reader.onload = () => setSettings((s) => ({ ...s, qrImage: reader.result }));
    reader.onerror = () => setQrErr("No se pudo leer la imagen. Intenta de nuevo.");
    reader.readAsDataURL(file);
  };

  return (
    <div className="stack">
      <div className="card pad">
        <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 14 }}>
          <Smartphone size={17} color="var(--yape)" /><span className="sm" style={{ fontWeight: 700 }}>QR de Yape</span>
        </div>
        <div style={{ display: "flex", gap: 14, alignItems: "center" }}>
          <div className="qr" style={{ width: 90, height: 90, margin: 0, flex: "none" }}>
            <img src={settings?.qrImage || YAPE_QR} alt="QR Yape actual" style={{ width: "100%", height: "100%", objectFit: "contain", borderRadius: 14 }} />
          </div>
          <div style={{ flex: 1 }}>
            <div className="xs mut" style={{ marginBottom: 8, lineHeight: 1.5 }}>
              Esto es lo que ve el cliente al pagar. Sube una foto de tu QR de Yape para reemplazarlo.
            </div>
            <label className="btn btn-ghost" style={{ display: "inline-flex", cursor: "pointer" }}>
              <Camera size={14} /> Cambiar QR
              <input type="file" accept="image/*" onChange={onQrFile} style={{ display: "none" }} />
            </label>
            {settings?.qrImage && (
              <button className="btn-ghost" style={{ marginLeft: 8 }} onClick={() => setSettings((s) => ({ ...s, qrImage: null }))}>
                Quitar
              </button>
            )}
          </div>
        </div>
        {qrErr && <div className="xs" style={{ color: "var(--danger)", marginTop: 8 }}>{qrErr}</div>}
      </div>

      <div className="card pad">
        <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 14 }}>
          <CircleDot size={17} color="var(--turf)" /><span className="sm" style={{ fontWeight: 700 }}>Precios de Vóley (Cancha A y B)</span>
        </div>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
          <Field label="Día (por hora)" value={prices.voley.dia} onChange={(v) => upd(["voley", "dia"], v)} />
          <Field label="Noche (por hora)" value={prices.voley.noche} onChange={(v) => upd(["voley", "noche"], v)} />
        </div>
      </div>

      <div className="card pad">
        <div className="sm" style={{ fontWeight: 700, marginBottom: 14 }}>Reglas</div>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
          <Field label="La noche empieza a las" value={prices.nightStart} onChange={(v) => upd(["nightStart"], v)} suffix="h" />
          <Field label="Descuento por 2h o más" value={prices.discount} onChange={(v) => upd(["discount"], v)} />
          <Field label="Separación para apartar" value={prices.deposit} onChange={(v) => upd(["deposit"], v)} />
        </div>
        <div className="xs mut" style={{ marginTop: 12 }}>El cliente yapea la separación para apartar la hora y paga el resto en la cancha. Los cambios se aplican al instante.</div>
      </div>
    </div>
  );
}
